function managementClick_management(action, d) {
  let id = Number(d.id),
  a = game.artist(id);
  switch (action) {
    case 'm-renew': case 'm-debut': modal(action === 'm-renew' ? '재계약 제안서': '데뷔 계약 제안서', `<form id="${action}" class="list"><input type="hidden" name="id" value="${id}"><label for="offer">계약 제안</label><select name="offer" id="offer">${offerOptions()}</select><p>${a?'기존 작품 배분은 유지하며 새 활동부터 변경됩니다. 최종 계약금은 인지도·신뢰에 따라 조정됩니다. 아래에서 확인하세요.':'90일 훈련·평균 능력 55 이상 필요'}</p>${a?Object.entries(DATA.terms).map(([k,t])=>`<p>${t.name}: 실제 계약금 ${money(game.renewalCost(a,k))}</p>`).join(''):''}<button class="primary">계약 승인</button></form>`);
    break;
    case 'm-release-trainee': case 'm-leave-confirm': modal('계약·소속 변경 확인', `<p>${action==='m-release-trainee'?'연습생 계약을 합의 종료합니다.':'팀에서 탈퇴합니다. 개인 계약과 기존 작품 배분·확정 일정은 유지됩니다. 1명만 남으면 팀은 휴지 상태가 됩니다.'}</p><div class="modal-actions">${btn('변경 승인',action==='m-release-trainee'?'m-trainee-release':'m-leave',`data-id="${id}"`,'danger')}</div>`);
    break;
    case 'm-trainee-release': mutate(() => game.releaseTrainee(id), '연습생 계약을 종료했습니다.');
    break;
    case 'm-leave': mutate(() => game.leaveTeam(id), '팀에서 탈퇴했습니다.');
    break;
    case 'm-team-confirm': {
      const impact = game.teamImpact(d.key);
      modal('팀 운영 변경', `<p>확정 일정 ${impact.jobs.length}건 · 기존 작품 ${impact.catalog}개 유지. 현재 협업 호흡 ${Math.round(impact.cohesion)}.</p>${impact.jobs.map(j=>`<p>${esc(j.name)} · ${date(j.due)}</p>`).join('')}<p>${d.op==='dissolve'?'팀을 해체합니다. 이름과 활동 이력은 보존되며, 개인 계약·기존 작품 배분·확정 일정은 유지됩니다.':d.op==='pause'?'새 팀 활동을 중단합니다. 이미 확정된 일정은 완료합니다.':'멤버 2명 이상이면 활동을 재개합니다.'}</p><div class="modal-actions">${btn('승인','m-team-apply',`data-key="${d.key}" data-op="${d.op}"`,'primary')}</div>`);
      break;
    }
    case 'm-team-apply': mutate(() => game.teamAction(d.key, d.op), '팀 설정을 변경했습니다.');
    break;
    case 'm-team': {
      let u = game.s.units.find(u => u.key === d.key);
      let list = game.s.artists.filter(a => DATA.roster[a.id].type === u.type && !game.s.units.some(u => u.ids.includes(a.id)));
      modal(esc(u.name) + ' 멤버 관리', `<p>새 멤버는 활동 중인 일정이 없어야 합니다. 기존 작품의 배분은 변경되지 않습니다.</p><form id="m-team-add"><input type="hidden" name="key" value="${u.key}"><label for="member">합류할 멤버</label><select name="id" id="member">${list.map(a=>`<option value="${a.id}">${DATA.roster[a.id].name}</option>`).join('')}</select><div class="modal-actions"><button class="primary" ${list.length?'':'disabled'}>팀 합류 승인</button></div></form>`);
      break;
    }
    case 'm-transfer': modal('삼자 합의 이적 검토', `<p>${DATA.roster[id].name} · 활동 중이면 일정 종료 후 진행하세요. 기존 작품 권리와 배분은 유지됩니다.</p>${game.s.rivals.map(r=>{let q=game.transferQuote(id,r.id);return `<div class="contract-row"><h3>${esc(r.name)}</h3><p>합의금 ${money(q.fee)} · 본인 ${q.consent?'동의':'거절'} · 상대 자금 ${q.affordable?'충족':'부족'} · 분야 ${q.fit?'적합':'불일치'}</p>${btn('이적 최종 검토','m-transfer-confirm',`data-id="${id}" data-rival="${r.id}"`,'soft',!q.consent||!q.affordable||!q.fit||game.busy(String(id)))}</div>`;}).join('')}`);
    break;
    case 'm-transfer-confirm': {
      let q = game.transferQuote(id, d.rival),
      r = game.s.rivals.find(r => r.id === Number(d.rival));
      modal('합의 이적 승인', `<p>${DATA.roster[id].name} → ${esc(r.name)}</p><p>회사는 ${money(q.fee)}을 받습니다. 전속계약과 팀 소속은 종료되고 작품 배분은 유지됩니다.</p>${btn('삼자 합의 승인','m-transfer-apply',`data-id="${id}" data-rival="${r.id}"`,'primary')}`);
      break;
    }
    case 'm-transfer-apply': mutate(() => game.transfer(id, d.rival), '합의 이적을 완료했습니다.');
    break;
  }
}
$('#modal-root').addEventListener('submit', ev => {
  let f = ev.target;
  if (!f.getAttribute('id')?.startsWith('m-')) return;
  ev.preventDefault();
  let data = new FormData(f);
  try {
    switch (f.getAttribute('id')) {
      case 'm-contract': mutate(() => game.sign(data.get('id'), data.get('offer')), '계약을 체결했습니다.');
      break;
      case 'm-renew': mutate(() => game.renew(data.get('id'), data.get('offer')), '재계약했습니다.');
      break;
      case 'm-debut': mutate(() => game.debut(data.get('id'), data.get('offer')), '정식 아티스트로 데뷔했습니다.');
      break;
      case 'm-team-add': mutate(() => game.teamAction(data.get('key'), 'add', Number(data.get('id'))), '팀 멤버가 합류했습니다.');
      break;
    }
  } catch (e) {
    $('#modal-error').textContent = e.message;
  }
});


