'use strict';
let releaseScope = 'own', chartMetric = 'streams', compareReleases = [], traineeView = 'all';
const menuGroups = {
  home:[['home', '홈'], ['goals', '목표']],
  inbox:[['inbox', '수신함']],
  artists:[['artists', '아티스트'], ['training', '연습생'], ['casting', '캐스팅'], ['teams', '팀·계약']],
  projects:[['projects', '프로젝트'], ['music', '발매 성과'], ['schedule', '통합 일정']],
  company:[['company', '회사·가치'], ['staff', '직원 관리'], ['recruit', '직원 고용'], ['finance', '재정']],
  industry:[['industry', '라이벌'], ['charts', '음악 차트']]
};
function pageGroup(p) {
  return Object.keys(menuGroups).find(group => menuGroups[group].some(([id]) => id === p)) || 'home';
}
function sectionTabs() {
  return `<nav class="section-tabs" aria-label="영역 내 메뉴">${menuGroups[pageGroup(page)].map(([id,label])=>btn(label,'nav',`data-page="${id}"`,page===id?'active':'')).join('')}${btn('하루 기록','m-day-log','','link')}${btn('저장·복구','m-saves','','link')}</nav>`;
}
function saveStatusLabel() {
  let meta = saveStore.read('next-stage-save-meta'),
  date = meta?.at ? new Date(meta.at): null;
  if (!saveOK && saveStore.hasAutoChanged()) return '다른 탭 저장 감지 · 현재 진행 백업 필요';
  return saveOK ? '저장됨' +(date && Number.isFinite(date.getTime()) ? ' · ' + date.toLocaleTimeString('ko-KR', { timeZone: 'Asia/Seoul', hour: '2-digit', minute: '2-digit' }): ''): '저장 실패 · JSON 백업 필요';
}
function todayTasks_market() {
  let s = game.s,
  tasks = [];
  for (const i of s.incidents) if (i.state === 'open') tasks.push({
    priority: 0,
    label: '사건 대응 · ' + i.name + ' · ' +(i.expires - s.day) + '일 남음',
    action: 'm-incident-open',
    args: `data-id="${i.id}"`
  });
  if (s.cash < game.fixed * 2) tasks.push({
    priority: 0,
    label: '운영 자금 확인 · ' + money(s.cash),
    action: 'nav',
    args: 'data-page="finance"'
  });
  for (const a of s.artists) if (a.contract - s.day <= 90) tasks.push({
    priority: 1,
    label: DATA.roster[a.id].name + ' 재계약 · ' +(a.contract - s.day) + '일 남음',
    action: 'm-renew',
    args: `data-id="${a.id}"`
  });
  for (const a of s.trainees) if (s.day - a.signed >= 90 && game.readiness(a) >= 55) tasks.push({
    priority: 2,
    label: DATA.roster[a.id].name + ' 데뷔 조건 충족',
    action: 'm-debut',
    args: `data-id="${a.id}"`
  });
  if (!s.artists.length && !s.trainees.length) tasks.push({
    priority: 2,
    label: '첫 인재 모집 시작',
    action: 'casting-modal',
    args: ''
  });
  return tasks.sort((a, b) => a.priority - b.priority);
};
function releaseRow(row) {
  let c = row.release,
  m = c.market,
  w = game.weekStats(c);
  return `<article class="contract-row"><div class="row between wrap"><div><h3>${esc(c.name)}</h3><small>${esc(m.artistName)} · ${esc(row.company)} · ${date(m.startDay)} · ${m.format==='physical'?'실물 싱글':'음원 싱글'}</small></div>${btn('작품 성과','m-release',`data-uid="${m.uid}"`,'soft small')}</div><p>최근 7일 ${w.streams.toLocaleString()}회 재생 · ${m.format==='physical'?w.sales.toLocaleString()+'장 판매':'실물 미제작'} / 누적 ${m.streams.toLocaleString()}회${m.format==='physical'?' · '+m.sales.toLocaleString()+'장':''}</p>${btn(compareReleases.includes(m.uid)?'비교 선택됨':'비교에 추가','m-compare-select',`data-uid="${m.uid}"`,'link small')}</article>`;
}
function music() {
  let rows = game.allReleases().filter(row => releaseScope === 'all' || releaseScope === 'own' && row.own || releaseScope === 'rival' && !row.own).sort((a, b) => b.release.market.startDay - a.release.market.startDay);
  return heading('발매 성과', '판매·재생·정산을 작품별로 확인하세요.', btn('선택 작품 비교 (' + compareReleases.length + '/3)', 'm-compare', '', 'primary', compareReleases.length < 2)) + `<div class="tabs">${[['own','우리 회사'],['rival','라이벌'],['all','전체']].map(([id,label])=>btn(label,'m-release-scope',`data-scope="${id}"`,releaseScope===id?'active':'')).join('')}</div>` + panel('최근 발매작', rows.slice(0, 60).map(releaseRow).join('') || '<p>아직 집계할 작품이 없습니다.</p>') + `<p class="muted">최근 60개 작품 표시. 이전 작품은 프로젝트의 발매 목록에서도 열 수 있습니다.</p>`;
}
function charts_market() {
  let rows = game.charts(chartMetric);
  return heading('참여 레이블 차트', '우리 회사와 라이벌 4곳만 포함합니다. 전체 음악 시장 순위가 아닙니다.', btn('선택 작품 비교', 'm-compare', '', 'soft', compareReleases.length < 2)) + `<div class="tabs">${btn('주간 스트리밍','m-chart','data-metric="streams"',chartMetric==='streams'?'active':'')}${btn('주간 음반 판매','m-chart','data-metric="sales"',chartMetric==='sales'?'active':'')}</div>` + panel('최근 7일 순위', rows.slice(0, 30).map((row, index) => `<div class="chart-row"><strong class="rank">${index+1}</strong><div class="spacer"><h3>${esc(row.release.name)}</h3><small>${esc(row.company)} · ${esc(row.release.market.artistName)}</small><p>${row.week[chartMetric].toLocaleString()}${chartMetric==='streams'?'회':'장'}</p>${btn('성과 보기','m-release',`data-uid="${row.release.market.uid}"`,'link small')}${btn('비교 선택','m-compare-select',`data-uid="${row.release.market.uid}"`,'link small')}</div></div>`).join('') || '<p>최근 7일 집계가 없습니다.</p>');
}
function releaseGraph(c, metric) {
  let bins = c.market.weeks.slice(- 12);
  if (!bins.length) return '<p>아직 주간 기록이 없습니다.</p>';
  let max = Math.max(1, ... bins.map(w => w[metric]));
  return `<svg viewBox="0 0 520 170" class="release-graph" role="img" aria-label="최근 12주 ${metric==='streams'?'스트리밍':'판매'} 추이"><title>${metric==='streams'?'스트리밍':'음반 판매'} · 최고 ${max.toLocaleString()}</title><line x1="12" y1="135" x2="508" y2="135" stroke="#cbd5e1"/>${bins.map((w,i)=>{let width=480/bins.length-6,x=20+i*480/bins.length,h=w[metric]/max*110;return `<rect x="${x}" y="${135-h}" width="${Math.max(4,width)}" height="${h}" rx="3" fill="#1265ef"><title>${w.week+1}주차 ${w[metric].toLocaleString()}</title></rect><text x="${x}" y="154" font-size="10" fill="#52627c">${w.week+1}주</text>`;}).join('')}</svg><small>최근 ${bins.length}개 주간 · 현재 주는 집계 중 · 최고 ${max.toLocaleString()}${metric==='streams'?'회':'장'}</small>`;
}
