UIEvents.onChange('operations', ev => {
  const target = ev.target;
  try {
    if (target.dataset.controlId !== undefined) {
      const a = game.talent(Number(target.dataset.controlId));
      game.setTrainingControl(a.id, target.value, a.trainingGoal);
      save();
      traineeDetail(a.id);
    } else if (target.dataset.goalId !== undefined) {
      const a = game.talent(Number(target.dataset.goalId));
      game.setTrainingControl(a.id, a.trainingMode, target.value);
      save();
      traineeDetail(a.id);
    } else if (target.dataset.growthId !== undefined) {
      traineeGraphMetric = Number(target.value);
      traineeDetail(target.dataset.growthId);
    } else if (target.dataset.trainingId !== undefined) {
      game.transaction(() => game.setTraining(Number(target.dataset.trainingId), target.value));
      save();
      render();
      traineeDetail(target.dataset.trainingId);
      toast('훈련 계획을 변경했습니다.');
    };
    if (target.id === 'promotion') budgetPreview();
  } catch (e) {
    toast(e.message);
  }
});


